"""Browser suite 2: edit pages, password reset, courses page, subject-in-use guard, cancel form, one form per semester."""
from helpers import *
import os
try:
    from playwright.sync_api import sync_playwright
except ImportError:
    sys.exit("Browser tests need Playwright:  pip install playwright   then   playwright install chromium")
SHOTS = os.path.join(REPO, "tests", "screenshots")
os.makedirs(SHOTS, exist_ok=True)
B = BASE

with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_context(viewport={"width":1280,"height":900}).new_page()
    dl=[]; pg.on("dialog",lambda d:(dl.append(d.message),d.accept())); errs=[]; pg.on("pageerror",lambda e:errs.append(str(e)))
    pg.goto(B); pg.click(".portal-link"); pg.fill("input[name=username]","admins"); pg.fill("input[name=password]","admins"); pg.click("input[name=submit]"); pg.wait_for_url("**/adminindex.php")
    pg.click("a.nav-link:has-text('Students')"); pg.wait_for_url("**/userreg.php")
    pg.click("a:has-text('EDIT')"); pg.wait_for_url("**/edituser.php*"); pg.wait_for_timeout(200)
    check("edit student page shows the form exactly once", pg.locator("input[name=username]").count()==1 and pg.locator("form.cmxform").count()==1)
    check("form is pre-filled with the student's data", pg.input_value("input[name=fname]")=="Karl Macniel" and pg.input_value("input[name=snum]")=="2014-052")
    pg.screenshot(path=SHOTS+"/b2_edit_user.png",full_page=True)
    pg.fill("input[name=lname]","Flores-Edited"); pg.fill("input[name=password]","brandnew1"); pg.click("input[name=save]"); pg.wait_for_url("**/userreg.php")
    check("saving shows the success alert and returns to the list", pg.locator(".portal-notice").inner_text()=="Successfully updated the account", dl[-1:])
    check("changes are in the database", sql("select lname from studenttbl where studnum='2014-052'")=="Flores-Edited" and sql("select password from usertbl where username='dennis'").startswith("$2y$"))
    pg.click("a.nav-link:has-text('Subjects')"); pg.wait_for_url("**/subjectreg.php")
    pg.locator("tr",has_text="CS 103").locator("a:has-text('EDIT')").click(); pg.wait_for_url("**/editsubject.php*")
    check("subject edit form pre-filled incl. lab checkbox ticked", pg.input_value("input[name=scode]")=="CS 103" and pg.is_checked("input[name=islab]"))
    pg.screenshot(path=SHOTS+"/b2_edit_subject.png",full_page=True)
    pg.fill("input[name=sroom]","Lab 2"); pg.click("input[name=save]"); pg.wait_for_url("**/subjectreg.php")
    check("subject saved", sql("select room from subjecttbl where subjectcode='CS 103'")=="Lab 2")
    pg.locator("tr",has_text="IT202").locator("summary").click(); pg.locator("tr",has_text="IT202").locator("button.link-button").click(); pg.wait_for_timeout(400)
    sql("delete from student_subject"); sql("insert into student_subject (studentID,subjects,totalunits,approved,semester,school_year) values ('2014-052','IT202',2,0,'1st Sem','2026 - 2027')")
    pg.reload(); pg.locator("tr",has_text="IT202").locator("summary").click(); pg.locator("tr",has_text="IT202").locator("button.link-button").click(); pg.wait_for_timeout(500)
    check("deleting a subject used in a form: confirm, then explanation and nothing deleted", "used in 1 enrollment form" in pg.locator(".portal-notice").inner_text() and sql("select count(*) from subjecttbl where subjectcode='IT202'")=="1", dl[-2:])
    pg.click("a.nav-link:has-text('Courses')"); pg.wait_for_url("**/courses.php"); pg.screenshot(path=SHOTS+"/b2_courses.png",full_page=True)
    pg.fill("#course_code","TESTBA"); pg.fill("#course_title","Business Admin"); pg.click("input[value='Add course']"); pg.wait_for_url("**/courses.php"); pg.wait_for_timeout(200)
    check("course added through the form", sql("select count(*) from courses_tbl where course_code='testba'")=="1" and "added" in pg.locator(".portal-notice").inner_text(), dl[-1:])
    pg.locator("tr",has_text="Business Admin").locator("a:has-text('EDIT')").click(); pg.wait_for_url("**/courses.php?edit=*")
    check("edit mode switches the form to Save changes", pg.locator("input[value='Save changes']").count()==1)
    pg.goto(B+"Admin/courses.php")
    pg.locator("tr",has_text="BSIT").locator("summary").click(); pg.locator("tr",has_text="BSIT").locator("button.link-button").click(); pg.wait_for_timeout(400)
    check("deleting BSIT explains why it can't", "cannot be deleted" in pg.locator(".portal-notice").inner_text(), pg.locator(".portal-notice").inner_text())
    pg.locator("tr",has_text="Business Admin").locator("summary").click(); pg.locator("tr",has_text="Business Admin").locator("button.link-button").click(); pg.wait_for_timeout(400)
    check("deleting the empty course works", sql("select count(*) from courses_tbl where course_code='testba'")=="0")
    pg.click("a.nav-link:has-text('Approvals')"); pg.wait_for_url("**/approvals.php"); pg.screenshot(path=SHOTS+"/b2_approvals.png",full_page=True)
    check("approvals shows semester", "1st Sem 2026 - 2027" in pg.inner_text("body"))
    pg.click("a.nav-link:has-text('Log Out')"); pg.wait_for_url("**/index.php")
    pg.click(".portal-link"); pg.fill("input[name=username]","dennis"); pg.fill("input[name=password]","brandnew1"); pg.click("input[name=submit]"); pg.wait_for_url("**/studentindex.php")
    check("student can log in with the admin-reset password", pg.locator(".portal-notice").inner_text()=="Successfully log in as Student")
    pg.goto(B+"student/report.php"); pg.screenshot(path=SHOTS+"/b2_student_report.png",full_page=True)
    pg.locator("summary",has_text="Cancel").click(); pg.get_by_role("button",name="Cancel enrollment").click(); pg.wait_for_timeout(500)
    check("student cancels the pending form (confirm + message)", sql("select count(*) from student_subject")=="0" and "cancelled" in pg.locator(".portal-notice").inner_text(), dl[-2:])
    pg.goto(B+"student/enroll.php"); pg.check("input[value=IT201]"); pg.click("input[name=register]"); pg.wait_for_url("**/showsubs.php")
    pg.click("input[name=reg]"); pg.wait_for_url("**/studentindex.php")
    pg.goto(B+"student/enroll.php?sem=1st+Sem")
    form_link = pg.get_by_role("link", name="View submitted form", exact=True)
    check("submitted semester links to the saved form before selection", form_link.is_visible() and pg.locator("input[value=IT202]").is_disabled())
    form_link.click()
    check("report opens on the student's specific form", pg.locator("tr:target").count() == 1 and "Pending" in pg.locator("tr:target").inner_text())
    check("no JavaScript errors", not errs, errs); b.close()
finish()
